/* ============================================
   TEXTAREA COMPONENT
   Multi-line text input with label and counter
   ============================================ */

.ds-textarea {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200); /* 8px */
  width: 100%;
}

/* ============================================
   LABEL
   ============================================ */

/* ============================================
   FIELD
   ============================================ */

.ds-textarea__field {
  width: 100%;
  padding: var(--padding-200) var(--padding-400); /* 8px 16px */
  border: var(--border-025) solid var(--color-input-border-primary);
  border-radius: var(--radius-300); /* 12px */
  background-color: var(--color-input-bg-primary);

  /* Typography */
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-input-text-primary);

  /* Transitions */
  transition: border-color var(--motion-duration-base) var(--motion-ease-standard), background-color var(--motion-duration-base) var(--motion-ease-standard);
  outline: none;
  box-sizing: border-box;
}

.ds-textarea__field::placeholder {
  color: var(--color-input-text-placeholder);
}

.ds-textarea__field:hover:not(:focus):not(:disabled) {
  border-color: var(--color-input-border-hover);
}

.ds-textarea__field:focus {
  border-color: var(--color-input-border-selected);
  background-color: var(--color-input-bg-primary);
}

/* ============================================
   FOOTER (helper + counter)
   ============================================ */

.ds-textarea__counter {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-tertiary);
  flex-shrink: 0;
}

/* ============================================
   ERROR STATE
   ============================================ */

.ds-textarea--error .ds-textarea__field {
  border-color: var(--color-status-error-border);
}

.ds-textarea--error .ds-textarea__field:focus {
  border-color: var(--color-status-error-border);
}

.ds-textarea--error .ds-textarea__counter {
  color: var(--color-status-error-border);
}

/* ============================================
   DISABLED STATE
   ============================================ */

.ds-textarea--disabled .ds-textarea__field {
  background-color: var(--color-input-bg-disabled);
  border-color: var(--color-input-border-disabled);
  color: var(--color-input-text-disabled);
  cursor: not-allowed;
}

.ds-textarea--disabled .ds-textarea__field::placeholder {
  color: var(--color-input-text-disabled);
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-textarea--compact .ds-textarea__field {
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

'use client';

import React from 'react';
import { Field } from '../Field/Field';
import './Textarea.css';

/** Props owned by Textarea itself — everything else falls through to the <textarea>. */
type TextareaOwnProps = {
  /** Textarea label text */
  label?: string;
  /** Current value */
  value?: string;
  /** Component size */
  size?: 'default' | 'compact';
  /** Error state — shows error styling and message */
  error?: boolean;
  /** Helper or error message displayed below */
  helperText?: string;
  /** Whether the textarea is resizable */
  resize?: 'none' | 'vertical' | 'horizontal' | 'both';
  /** Max character count — shows counter when set */
  maxLength?: number;
  /**
   * Convenience callback receiving the value directly.
   * Fires alongside `onChange`, which keeps the standard React event signature
   * so form libraries work unmodified.
   */
  onValueChange?: (value: string) => void;
  /** Additional CSS classes — applied to the wrapper, not the <textarea> */
  className?: string;
  /**
   * Legacy accessible-name prop.
   *
   * @deprecated Pass the native `aria-label` attribute instead.
   */
  ariaLabel?: string;
};

export interface TextareaProps
  extends TextareaOwnProps,
    Omit<React.ComponentPropsWithoutRef<'textarea'>, keyof TextareaOwnProps> {}

/**
 * Multi-line text input with optional label, helper text, character counter
 * and error state.
 *
 * Forwards a ref to the underlying `<textarea>` and spreads unrecognised props
 * onto it.
 */
export const Textarea = React.forwardRef<HTMLTextAreaElement, TextareaProps>(
  (
    {
      label,
      placeholder = '',
      value = '',
      rows = 4,
      size = 'default',
      disabled = false,
      required = false,
      error = false,
      helperText,
      resize = 'vertical',
      maxLength,
      onChange,
      onValueChange,
      className = '',
      ariaLabel,
      name,
      id,
      style,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-textarea';

    const classes = [
      baseClass,
      size === 'compact' ? `${baseClass}--compact` : '',
      error ? `${baseClass}--error` : '',
      disabled ? `${baseClass}--disabled` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      onChange?.(e);
      onValueChange?.(e.target.value);
    };

    const inputId = id || name || label?.toLowerCase().replace(/\s+/g, '-');
    const charCount = value?.length || 0;

    return (
      <Field
        className={classes}
        label={label}
        helperText={helperText}
        error={error}
        required={required}
        disabled={disabled}
        size={size}
        id={inputId}
        aside={
          maxLength ? (
            <span className={`${baseClass}__counter`} aria-live="polite" aria-atomic="true">
              {charCount}/{maxLength}
            </span>
          ) : undefined
        }
      >
        <textarea
          {...rest}
          ref={ref}
          className={`${baseClass}__field`}
          id={inputId}
          name={name}
          value={value}
          placeholder={placeholder}
          rows={rows}
          disabled={disabled}
          required={required}
          maxLength={maxLength}
          aria-label={ariaLabel || rest['aria-label'] || label}
          aria-invalid={error}
          aria-describedby={helperText ? `${inputId}-helper` : rest['aria-describedby']}
          onChange={handleChange}
          style={{ resize, ...style }}
        />
      </Field>
    );
  },
);

Textarea.displayName = 'Textarea';
